import{_ as t,o as a,c as i,a3 as r}from"./chunks/framework.CchDE9cb.js";const p=JSON.parse(`{"title":"Reviews and compliance","description":"An index of CapacityLens's dated security review, threat model, control inventories, ASVS ledger and mutation-testing reviews.","frontmatter":{"title":"Reviews and compliance","description":"An index of CapacityLens's dated security review, threat model, control inventories, ASVS ledger and mutation-testing reviews."},"headers":[],"relativePath":"security/reviews.md","filePath":"security/reviews.md","lastUpdated":null}`),s={name:"security/reviews.md"};function o(n,e,c,d,h,l){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="reviews-and-compliance" tabindex="-1">Reviews and compliance <a class="header-anchor" href="#reviews-and-compliance" aria-label="Permalink to &quot;Reviews and compliance&quot;">​</a></h1><p>CapacityLens keeps a set of dated, evidence-based security documents alongside the code, instead of a one-off claim of &quot;secure by design&quot;. They are written for security reviewers, auditors and technical evaluators, not for a first read of the product — start at the <a href="/capacitylens/security/">Security overview</a> if that is what you need. Each artifact below is reproduced as-is on its own page; this page just explains what each one is and when to reach for it.</p><h2 id="owasp-asvs-5-0-0-ledger" tabindex="-1"><a href="/capacitylens/security/owasp-asvs-5.0.0">OWASP ASVS 5.0.0 ledger</a> <a class="header-anchor" href="#owasp-asvs-5-0-0-ledger" aria-label="Permalink to &quot;[OWASP ASVS 5.0.0 ledger](/security/owasp-asvs-5.0.0)&quot;">​</a></h2><p>Dated 2026-07-14. Every one of the 345 requirements in the OWASP Application Security Verification Standard 5.0.0 (covering Levels 1 to 3), assessed as Pass, Partial, Gap or Not Applicable, with the repository evidence behind each one. Read this when you need to check a specific control by ASVS requirement id, or want the complete picture rather than a summary.</p><h2 id="security-review-—-2026-07-14" tabindex="-1"><a href="/capacitylens/security/security-review-2026-07-14">Security review — 2026-07-14</a> <a class="header-anchor" href="#security-review-—-2026-07-14" aria-label="Permalink to &quot;[Security review — 2026-07-14](/security/security-review-2026-07-14)&quot;">​</a></h2><p>A point-in-time source-code review against the ASVS ledger above, plus the OWASP Top 10 and API Security Top 10. It explains the review&#39;s scope and method, lists findings and how they were treated, and states plainly what is a code guarantee, what is an inherited library guarantee, and what is left to the self-hosting operator. Read this for the narrative version of the ASVS ledger — what was found, fixed and accepted, and why.</p><h2 id="threat-model" tabindex="-1"><a href="/capacitylens/security/threat-model">Threat model</a> <a class="header-anchor" href="#threat-model" aria-label="Permalink to &quot;[Threat model](/security/threat-model)&quot;">​</a></h2><p>Dated 2026-07-14. States CapacityLens&#39;s security objectives in plain terms, lists the assets and trust boundaries being protected, names the realistic attackers (a malicious teammate, a credential-stuffing bot, a compromised identity provider, a careless operator, and more), and maps each abuse case to the controls and tests that address it. Ends with the risks that are consciously accepted rather than fixed. Read this to understand <em>why</em> a control exists, not just that it does.</p><h2 id="control-inventories" tabindex="-1"><a href="/capacitylens/security/control-inventories">Control inventories</a> <a class="header-anchor" href="#control-inventories" aria-label="Permalink to &quot;[Control inventories](/security/control-inventories)&quot;">​</a></h2><p>Dated 2026-07-14. The reference tables behind the threat model and ASVS ledger: every entry point and untrusted input, every class of sensitive data and how long it is kept, the full cryptographic inventory (what algorithm protects what, and its key lifecycle), service and rate limits, and the audit/security event log. Read this when you need the specific technical detail — for example, exactly what algorithm hashes a password, or exactly how long a session token lives.</p><h2 id="mutation-test-review-—-2026-07-15" tabindex="-1"><a href="/capacitylens/security/mutation-review-2026-07-15">Mutation-test review — 2026-07-15</a> <a class="header-anchor" href="#mutation-test-review-—-2026-07-15" aria-label="Permalink to &quot;[Mutation-test review — 2026-07-15](/security/mutation-review-2026-07-15)&quot;">​</a></h2><p>The first review of CapacityLens&#39;s mutation-testing results (a technique that deliberately introduces small bugs into the code to check whether the test suite catches them) read for security meaning rather than raw score. It found and fixed one real defence-in-depth defect in tenant-data validation, and records which parts of the codebase the mutation score does — and does not — cover.</p><h2 id="mutation-test-review-—-2026-07-18" tabindex="-1"><a href="/capacitylens/security/mutation-review-2026-07-18">Mutation-test review — 2026-07-18</a> <a class="header-anchor" href="#mutation-test-review-—-2026-07-18" aria-label="Permalink to &quot;[Mutation-test review — 2026-07-18](/security/mutation-review-2026-07-18)&quot;">​</a></h2><p>A follow-up review after a test-scope correction (two React hooks had been wrongly included in the mutation run). Confirms the corrected 92.37% score, with tenant isolation, private-name handling and password-reset failure mapping all still at 100%. Read the two mutation reviews together for the current state of that evidence and what it does not claim to cover.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><p>Report a vulnerability through the process in the <a href="https://github.com/Kevinjohn/capacitylens/blob/main/SECURITY.md" target="_blank" rel="noreferrer">security policy</a>, or go back to the <a href="/capacitylens/security/">Security overview</a> for the plain-language summary.</p>',16)])])}const m=t(s,[["render",o]]);export{p as __pageData,m as default};
